//! Fixed wire constants of the device-bound sign-in.
//!
//! The two CLEP challenge blobs are the values for a machine with no readable hardware fingerprint
//! (all-zero SMBIOS and disk serial), which is what this client submits; they are byte-for-byte
//! constant.

/// Token-broker `User-Agent` sent on every account-service request.
pub const USER_AGENT: &str =
    "MSAWindows/55 (OS 10.0.26100.0.0 ge_release; IDK 10.0.26100.5074 ge_release; Cfg 16.000.29325.00; Test 0)";

/// The component-unavailable marker (`0x80070002`), sent as the `error` attribute of a `Component`.
pub const COMPONENT_UNAVAILABLE: &str = "-2147024894";

/// CLEP challenge blob V2 (component `8196`), base64.
pub const CLEP_CHALLENGE_V2: &str = "";

/// CLEP challenge blob V4 (component `8197`), base64.
pub const CLEP_CHALLENGE_V4: &str = "";
